def calculate_k(A, B, d):
    k = 0
    for m in A:
        for n in B:
            if abs(m - n) <= d:
                k += 1
    return k

A = range(1, 2001)
B = range(1, 2017)
d = 1000
print(calculate_k(A, B, d))

def calculate_k_shifted(x, size_A, size_B, d):
    # A = {x+1, ..., x+size_A}
    # B = {1, ..., size_B}
    k = 0
    for m in range(x + 1, x + size_A + 1):
        # n in B such that m-d <= n <= m+d
        low = max(1, m - d)
        high = min(size_B, m + d)
        if low <= high:
            k += (high - low + 1)
    return k

size_A = 2000
size_B = 2016
d = 1000
max_k = 0
best_x = 0
for x in range(-3000, 3000):
    k = calculate_k_shifted(x, size_A, size_B, d)
    if k > max_k:
        max_k = k
        best_x = x
print(f"max_k: {max_k}, best_x: {best_x}")

